export const renderUserInterfaceMainContainer = (
  container: HTMLElement
): void => {
  const appContainer = document.createElement('div');
  appContainer.className = 'app';
  container.appendChild(appContainer);

  const generateButton = document.createElement('button');
  generateButton.textContent = 'Generate';
  generateButton.addEventListener('click', () => {
    const settings: PasswordGenerationSettings = {
      length: 12,
      strengthLevel: 'high',
    };
    const generatedPassword = generatePassword(settings);
    const passwordDisplay = document.createElement('div');
    passwordDisplay.textContent = generatedPassword;
    passwordDisplay.style.fontSize = '2rem';
    passwordDisplay.style.color = '#00d9ff';
    appContainer.appendChild(passwordDisplay);
  });
  appContainer.appendChild(generateButton);

  const copyButton1 = document.createElement('button');
  copyButton1.textContent = 'Copy';
  copyButton1.addEventListener('click', () => {
    const passwordDisplay = document.querySelector('.password-display');
    if (passwordDisplay) {
      const password = passwordDisplay.textContent;
      if (password) {
        navigator.clipboard.writeText(password);
      }
    }
  });
  appContainer.appendChild(copyButton1);

  const copyButton2 = document.createElement('button');
  copyButton2.textContent = 'Copy';
  copyButton2.addEventListener('click', () => {
    const passwordDisplay = document.querySelector('.password-display');
    if (passwordDisplay) {
      const password = passwordDisplay.textContent;
      if (password) {
        navigator.clipboard.writeText(password);
      }
    }
  });
  appContainer.appendChild(copyButton2);

  const lengthSlider = document.createElement('input');
  lengthSlider.type = 'range';
  lengthSlider.min = '8';
  lengthSlider.max = '32';
  lengthSlider.value = '12';
  lengthSlider.addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    updatePasswordLength(value);
  });
  appContainer.appendChild(lengthSlider);

  const strengthSlider = document.createElement('input');
  strengthSlider.type = 'range';
  strengthSlider.min = '5';
  strengthSlider.max = '7';
  strengthSlider.value = '5';
  strengthSlider.addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    updatePasswordStrength(value);
  });
  appContainer.appendChild(strengthSlider);
};

export const generatePassword = (settings: PasswordGenerationSettings): string => {
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
  let password = '';
  const length = settings.length;
  const strengthLevel = settings.strengthLevel;
  if (strengthLevel === 'low') {
    for (let i = 0; i < length; i++) {
      password += characters.charAt(Math.floor(Math.random() * characters.length));
    }
  } else if (strengthLevel === 'medium') {
    for (let i = 0; i < length; i++) {
      password += characters.charAt(Math.floor(Math.random() * characters.length));
    }
  } else if (strengthLevel === 'high') {
    for (let i = 0; i < length; i++) {
      password += characters.charAt(Math.floor(Math.random() * characters.length));
    }
  }
  return password;
};

